import sys

def main():
    s, p = sys.stdin.read().split()
    toks = []
    i = 0
    while i < len(p):
        if i + 1 < len(p) and p[i + 1] in '*+':
            toks.append((p[i], p[i + 1]))
            i += 2
        else:
            toks.append((p[i], ''))
            i += 1
    n = len(s)
    prev = [False] * (n + 1)
    prev[0] = True
    for c, op in toks:
        cur = [False] * (n + 1)
        if op == '*':
            cur[0] = prev[0]
        for i in range(1, n + 1):
            m = c == '.' or c == s[i - 1]
            if op == '':
                cur[i] = prev[i - 1] and m
            elif op == '*':
                cur[i] = prev[i] or (m and cur[i - 1])
            else:
                cur[i] = m and (prev[i - 1] or cur[i - 1])
        prev = cur
    print('true' if prev[n] else 'false')

