import sys

def match(s, p):
    if not p:
        return not s
    first = bool(s) and (p[0] == '.' or p[0] == s[0])
    if len(p) >= 2 and p[1] == '*':
        return match(s, p[2:]) or (first and match(s[1:], p))
    if len(p) >= 2 and p[1] == '+':
        return first and match(s[1:], p[0] + '*' + p[2:])
    return first and match(s[1:], p[1:])

s, p = sys.stdin.read().split()
print('true' if match(s, p) else 'false')

