def gen(rng):
    def fmt(s, p):
        return s + '\n' + p
    def rand_pat(k, alpha):
        out = []
        for _ in range(k):
            c = rng.choice(alpha + '.')
            op = rng.choice(['', '', '*', '+'])
            out.append(c + op)
        return ''.join(out)
    tests = [fmt('aaab', 'a*b'), fmt('a', 'a'), fmt('a', 'b'), fmt('a', '.'), fmt('a', 'a+'), fmt('a', 'b*a'), fmt('ab', 'a'),
             fmt('aa', 'a'), fmt('a', 'a*a+'), fmt('abc', '.*'), fmt('abc', '.+c'), fmt('ab', 'a+b+c*'), fmt('a', 'b*'),
             fmt('aab', 'c*a*b'), fmt('abab', '.*b'), fmt('abab', '.+a'), fmt('b', 'a*b*')]
    for _ in range(40):
        s = ''.join(rng.choice('ab') for _ in range(rng.randint(1, 8)))
        if rng.random() < 0.4:
            p = rand_pat(rng.randint(1, 6), 'ab')
        else:
            p = ''
            i = 0
            while i < len(s):
                j = i
                while j < len(s) and s[j] == s[i]:
                    j += 1
                r = rng.random()
                if r < 0.3:
                    p += s[i:j]
                elif r < 0.55:
                    p += s[i] + '+'
                elif r < 0.7:
                    p += s[i] + '*'
                elif r < 0.85:
                    p += '.' * (j - i)
                else:
                    p += '.+'
                if rng.random() < 0.3:
                    p += rng.choice('ab.') + '*'
                i = j
            if rng.random() < 0.3 and len(p) > 1:
                k = rng.randrange(len(p))
                if p[k] in 'ab.':
                    p = p[:k] + rng.choice('ab.') + p[k + 1:]
        tests.append(fmt(s, p))
    # max-size cases
    tests.append(fmt('a' * 1000, 'a*' * 499 + 'c'))
    tests.append(fmt('a' * 1000, 'a*' * 500))
    tests.append(fmt('a' * 1000, 'a+' * 500))
    tests.append(fmt('a' * 999 + 'b', 'a*' * 498 + 'c*b'))
    tests.append(fmt('a' * 1000, '.' * 1000))
    tests.append(fmt('a' * 1000, '.' * 999 + 'b'))
    s = ''.join(rng.choice('ab') for _ in range(1000))
    tests.append(fmt(s, rand_pat(450, 'ab')))
    tests.append(fmt(s, '.*'))
    s2 = ''.join(rng.choice('ab') for _ in range(400))
    p2 = ''
    i = 0
    while i < len(s2):
        j = i
        while j < len(s2) and s2[j] == s2[i]:
            j += 1
        p2 += rng.choice([s2[i:j], s2[i] + '+', '.' * (j - i)])
        p2 += rng.choice(['', '', 'a*', 'b*'])
        i = j
    tests.append(fmt(s2, p2))
    return tests

